Q: Android error getSlotFromBufferLocked: unknown buffer: 0xa9fb8d90 A: <blockquote>
  <p>Added internet permission</p>
</blockquote>

<pre><code>&lt;?xml version="1.0" encoding="utf-8"?&gt;
    &lt;manifest xmlns:android="http://schemas.android.com/apk/res/android"
        package="com.projectx.store"&gt;

        &lt;uses-permission android:name="android.permission.INTERNET" /&gt;

        &lt;application
            android:allowBackup="true"
            android:icon="@mipmap/ic_launcher"
            android:label="@string/app_name"
            android:roundIcon="@mipmap/ic_launcher_round"
            android:supportsRtl="true"
            android:theme="@style/AppTheme"&gt;
            &lt;activity android:name=".MainActivity"&gt;
                &lt;intent-filter&gt;
                    &lt;action android:name="android.intent.action.MAIN" /&gt;

                    &lt;category android:name="android.intent.category.LAUNCHER" /&gt;
                &lt;/intent-filter&gt;
            &lt;/activity&gt;
            &lt;activity android:name=".ViewAllStore" /&gt;
            &lt;activity android:name=".ViewStore"&gt;&lt;/activity&gt;
        &lt;/application&gt;

    &lt;/manifest&gt;
</code></pre>

Q: Scrape an image from website in Google sheets (using ImportXml) A: <p>Almost every website is using open graph these days, script below extracts og:image url and checks for it only within head for performance.</p>
<pre><code>/**
 * Google Apps Script custom function for Google Sheets.
 *
 * Usage in a cell:
 *   =GET_OG_IMAGE(A1)
 *
 * Fetches the URL in A1, parses the &lt;head&gt; section of the HTML,
 * finds &lt;meta property=&quot;og:image&quot; content=&quot;...&quot;&gt; (attribute order
 * doesn't matter) and returns the value of its &quot;content&quot; attribute.
 *
 * HOW TO INSTALL:
 * 1. Open your Google Sheet.
 * 2. Extensions -&gt; Apps Script.
 * 3. Delete any boilerplate code in Code.gs and paste this whole file in.
 * 4. Save (the disk icon or Ctrl/Cmd+S).
 * 5. Go back to the sheet and type =GET_OG_IMAGE(A1) in any cell,
 *    where A1 contains a URL.
 *
 * NOTE: Apps Script's UrlFetchApp does not support partial/streaming
 * downloads, so it always retrieves the full HTTP response body — there
 * is no way to physically stop downloading right at &lt;/head&gt;. This
 * function compensates by only *parsing* the &lt;head&gt;...&lt;/head&gt; portion
 * of the returned HTML (ignoring the rest of the page), which keeps the
 * regex work fast and avoids false matches in the page body.
 */
function GET_OG_IMAGE(url) {
  if (!url) return '';
  url = String(url).trim();
  if (!url) return '';

  try {
    var response = UrlFetchApp.fetch(url, {
      muteHttpExceptions: true,
      followRedirects: true,
      validateHttpsCertificates: true,
      headers: {
        // Some sites block requests with no/unusual User-Agent.
        'User-Agent': 'Mozilla/5.0 (compatible; GoogleSheetsOgImageBot/1.0)'
      }
    });

    var code = response.getResponseCode();
    if (code &lt; 200 || code &gt;= 400) {
      return 'Error: HTTP ' + code;
    }

    var html = response.getContentText();

    // Restrict search to the &lt;head&gt; section if we can find one.
    var headMatch = html.match(/&lt;head[^&gt;]*&gt;([\s\S]*?)&lt;\/head&gt;/i);
    var searchText = headMatch ? headMatch[1] : html;

    // Grab every &lt;meta ...&gt; tag in the head.
    var metaTags = searchText.match(/&lt;meta\b[^&gt;]*&gt;/gi) || [];

    for (var i = 0; i &lt; metaTags.length; i++) {
      var tag = metaTags[i];

      // Match property=&quot;og:image&quot; (also tolerate name=&quot;og:image&quot;, used by some sites).
      if (/(?:property|name)\s*=\s*[&quot;']og:image[&quot;']/i.test(tag)) {
        var contentMatch = tag.match(/content\s*=\s*[&quot;']([^&quot;']*)[&quot;']/i);
        if (contentMatch) {
          return decodeHtmlEntities_(contentMatch[1]);
        }
      }
    }

    return 'Not found';
  } catch (e) {
    return 'Error: ' + e.message;
  }
}

/**
 * Small helper to decode the handful of HTML entities that commonly
 * show up inside og:image URLs (e.g. &quot;&amp;amp;&quot; between query params).
 */
function decodeHtmlEntities_(str) {
  return str
    .replace(/&amp;amp;/g, '&amp;')
    .replace(/&amp;quot;/g, '&quot;')
    .replace(/&amp;#39;/g, &quot;'&quot;)
    .replace(/&amp;lt;/g, '&lt;')
    .replace(/&amp;gt;/g, '&gt;');
}
</code></pre>
